import base64
import io
from PIL import Image
import torch
from transformers import AutoProcessor, AutoModelForImageTextToText
import kagglehub

# ----------------- 1. 모델 로딩 (한 번만 실행) -----------------
GEMMA_PATH = kagglehub.model_download("google/gemma-3n/transformers/gemma-3n-e2b-it")
processor = AutoProcessor.from_pretrained(GEMMA_PATH)
model = AutoModelForImageTextToText.from_pretrained(
    GEMMA_PATH,
    torch_dtype=torch.float32,
).to("cpu")
print("Gemma-3n 모델 로딩 완료.")

# ----------------- 2. 분석할 이미지 입력 (Base64) -----------------
# 첫 번째 상황 이미지
BASE64_IMAGE_1 = ""
# 두 번째 상황 이미지
BASE64_IMAGE_2 = ""
 
# ----------------- 3. 단일 상황 분석을 위한 프롬프트 정의 -----------------
single_scene_prompt = """
You are an expert AI driving instructor. Analyze the provided image, which shows a specific driving situation from the driver's perspective. Your task is to create a detailed, actionable plan for this single scene.

### ANALYSIS INSTRUCTIONS:
1.  Thoroughly analyze the provided image to understand the road layout, signs, markings, traffic, and potential hazards.
2.  Infer the most likely immediate goal of the driver (e.g., "Safely navigate the intersection straight ahead").
3.  Create a clear, step-by-step action plan.
4.  List the most critical safety alerts.

### OUTPUT FORMAT:
Your entire response MUST be a single, valid JSON object. Do not include any text or explanations outside the JSON.

### JSON SCHEMA:
{
  "scene_analysis": {
    "description": "A concise summary of the key elements in the image.",
    "inferred_goal": "The most probable short-term driving goal."
  },
  "action_plan": [
    {
      "step": 1,
      "action": "A specific driving action.",
      "rationale": "The reason for this action, in Korean."
    }
  ],
  "safety_alerts": [
    "A list of critical potential hazards, in Korean."
  ]
}
"""

# ----------------- 4. 이미지 분석 함수 정의 (수정된 부분) -----------------
def analyze_driving_scene(image_base64_string):
    """Base64 이미지 문자열을 받아 AI 모델로 분석하고 JSON 결과를 반환하는 함수"""
    # Base64를 PIL 이미지 객체로 디코딩
    image_obj = Image.open(io.BytesIO(base64.b64decode(image_base64_string))).convert("RGB")
    
    # 1. 올바른 메시지 형식 정의: 이미지 부분은 딕셔너리 플레이스홀더로 대체합니다.
    messages = [
        {
            "role": "user",
            "content": [
                {"type": "image"},
                {"type": "text", "text": single_scene_prompt}
            ]
        }
    ]
    
    # 2. apply_chat_template을 사용하여 텍스트 프롬프트 문자열을 생성합니다.
    #    (tokenize=False로 설정하여 문자열만 반환받습니다)
    prompt = processor.apply_chat_template(messages, add_generation_prompt=True, tokenize=False)
    
    # 3. processor의 메인 호출을 사용하여 텍스트 프롬프트와 실제 이미지를 결합하고
    #    모델에 입력할 최종 텐서를 생성합니다.
    inputs = processor(text=prompt, images=[image_obj], return_tensors="pt").to("cpu")
    
    input_len = inputs["input_ids"].shape[-1]
    
    outputs = model.generate(
        **inputs,
        max_new_tokens=1536,
        temperature=0.5, # 창의성과 정확성의 균형
        disable_compile=True
    )
    
    # 모델의 출력에서 텍스트 부분만 추출하여 반환
    return processor.batch_decode(outputs[:, input_len:], skip_special_tokens=True, clean_up_tokenization_spaces=True)[0]

# ----------------- 5. 각 이미지에 대해 분석을 두 번 실행 -----------------
# (이하 코드는 기존과 동일하게 실행됩니다)
print("\n" + "="*50)
print("--- 첫 번째 상황 분석 시작 ---")
json_output_1 = analyze_driving_scene(BASE64_IMAGE_1)
print(json_output_1)
print("--- 첫 번째 상황 분석 완료 ---")
print("="*50)


print("\n" + "="*50)
print("--- 두 번째 상황 분석 시작 ---")
json_output_2 = analyze_driving_scene(BASE64_IMAGE_2)
print(json_output_2)
print("--- 두 번째 상황 분석 완료 ---")
print("="*50)

